import {equipmentStats,purchaseEquipment,selectEquipment} from './progression.mjs';
import {POSE_SECONDS} from './interactions.mjs';
import {PRESETS,APPEARANCES} from './catalog.mjs';
import {serviceTiles,findPath,waitingTiles,sameTile} from './grid.mjs';
export const station=(world,kind)=>world.clinic.items.find(i=>i.kind===kind&&i.x!==null);
function spawn(w,rng){w.patients.push({id:'p'+w.nextPatientId++,appearance:Math.floor(rng()*APPEARANCES.length)%APPEARANCES.length,stage:'toReception',tile:{...PRESETS[w.clinic.presetId].entrance},path:[],progress:0,checkedInOrder:null,seatId:null,examDuration:null,examRemaining:null,payout:null,paid:false,direction:0});route(w,w.patients.at(-1),serviceTiles(station(w,'counter')).patient);}
export function route(w,p,target){const path=findPath(w.clinic,p.tile,target);p.path=path??[];p.routeBlocked=path===null;p.progress=0;}
export function createWorld(clinic,rng=Math.random){const w={clinic:structuredClone(clinic),patients:[],doctor:{tile:{...serviceTiles(clinic.items.find(i=>i.kind==='exam')).staff},path:[],progress:0,direction:0},receptionist:{tile:{...serviceTiles(clinic.items.find(i=>i.kind==='counter')).staff},path:[],progress:0,direction:0},counter:null,exam:null,elapsed:0,arrivalRemaining:18,nextPatientId:1,nextQueueOrder:1,transactions:[]};spawn(w,rng);return w;}
function walk(p,dt){if(!p.path.length)return;p.progress+=dt*2;const next=p.path[0];p.direction=next.x>p.tile.x?0:next.y>p.tile.y?1:next.x<p.tile.x?2:3;if(p.progress>=1-1e-9){p.tile=p.path.shift();p.progress=Math.max(0,p.progress-1);}if(!p.path.length)p.progress=0;}
function sendToWait(w,p){p.stage='waiting';p.checkedInOrder=w.nextQueueOrder++;const taken=new Set(w.patients.map(p=>p.seatId).filter(Boolean));const seat=w.clinic.items.find(i=>i.kind==='chair'&&i.x!==null&&!taken.has(i.id));if(seat){p.seatId=seat.id;route(w,p,serviceTiles(seat).patient);}else{const tiles=waitingTiles(w.clinic);const used=w.patients.filter(a=>a.stage==='waiting'&&a.id!==p.id).map(a=>a.path.at(-1)??a.tile);route(w,p,tiles.find(t=>!used.some(u=>sameTile(u,t)))??tiles[0]??p.tile);}}
function step(w,dt,events,rng){w.elapsed+=dt;w.arrivalRemaining-=dt;if(w.arrivalRemaining<=1e-9){if(w.patients.length<8)spawn(w,rng);w.arrivalRemaining=18;}
for(const actor of [w.doctor,w.receptionist,...w.patients])walk(actor,dt);
for(const p of w.patients){if(p.stage==='checkIn'&&!w.receptionist.path.length){p.remaining-=dt;if(p.remaining<=1e-9){w.counter=null;sendToWait(w,p);}}else if(p.stage==='toExam'&&!p.routeBlocked&&!p.path.length&&!w.doctor.path.length&&sameTile(p.tile,serviceTiles(station(w,'exam')).patient)){p.stage=p.resumeStage??'seating';if(p.stage==='seating'&&!Number.isFinite(p.poseRemaining))p.poseRemaining=POSE_SECONDS;delete p.resumeStage;}else if(p.stage==='seating'){p.poseRemaining=Math.max(0,p.poseRemaining-dt);if(p.poseRemaining<=1e-9){p.stage='exam';p.poseRemaining=0;}}else if(p.stage==='exam'){p.examRemaining=Math.max(0,p.examRemaining-dt);if(p.examRemaining<=1e-9){p.stage='standing';p.poseRemaining=POSE_SECONDS;}}else if(p.stage==='standing'){p.poseRemaining=Math.max(0,p.poseRemaining-dt);if(p.poseRemaining<=1e-9){p.stage='toPayment';w.exam=null;route(w,p,serviceTiles(station(w,'counter')).patient);}}else if(p.stage==='payment'&&!w.receptionist.path.length){p.remaining-=dt;if(p.remaining<=1e-9){if(!p.paid){p.paid=true;w.clinic.coins=Math.min(Number.MAX_SAFE_INTEGER,w.clinic.coins+p.payout);w.clinic.completedVisits=Math.min(Number.MAX_SAFE_INTEGER,w.clinic.completedVisits+1);w.clinic.xp=Math.min(Number.MAX_SAFE_INTEGER,w.clinic.xp+10);events.push({xp:10,type:'payment',patientId:p.id,amount:p.payout});}w.counter=null;p.stage='exiting';route(w,p,PRESETS[w.clinic.presetId].entrance);}}}
w.patients=w.patients.filter(p=>!(p.stage==='exiting'&&!p.path.length&&sameTile(p.tile,PRESETS[w.clinic.presetId].entrance)));
if(!w.counter){const ready=w.patients.filter(p=>['toReception','toPayment'].includes(p.stage)&&!p.routeBlocked&&!p.path.length&&sameTile(p.tile,serviceTiles(station(w,'counter')).patient));const p=ready.find(p=>p.stage==='toPayment')??ready[0];if(p){w.counter=p.id;p.stage=p.stage==='toPayment'?'payment':'checkIn';p.remaining=p.resumeService?.stage===p.stage?p.resumeService.remaining:p.stage==='payment'?2:3;delete p.resumeService;}}
if(!w.exam){const p=w.patients.filter(p=>p.stage==='waiting').sort((a,b)=>a.checkedInOrder-b.checkedInOrder)[0];if(p&&!p.path.length){w.exam=p.id;p.seatId=null;p.stage='toExam';const e=equipmentStats(w.clinic.equipmentId);p.equipmentId=w.clinic.equipmentId;p.examDuration=e.duration;p.examRemaining=e.duration;p.payout=e.payout;route(w,p,serviceTiles(station(w,'exam')).patient);}}
}
export function advance(world,seconds,rng=Math.random){if(!Number.isFinite(seconds)||seconds<=0)return {world,events:[]};const w=structuredClone(world),events=[];let remaining=seconds;while(remaining>1e-9){const dt=Math.min(.05,remaining);step(w,dt,events,rng);remaining-=dt;}return {world:w,events};}
export function upgradeEquipment(w,id){const bought=purchaseEquipment(w,id);return bought.result.ok?selectEquipment(bought.world,id).world:w;}
